/bin/bash -lc 'if [ -z "$GALAXY_API_KEY_FILE" ] || [ ! -r "$GALAXY_API_KEY_FILE" ]; then echo '"'GALAXY_API_KEY_FILE unavailable'; exit 2; fi
api_key_value="'$(<"$GALAXY_API_KEY_FILE")
tool_path=$(python -c '"'import urllib.parse; print(urllib.parse.quote(\"toolshed.g2.bx.psu.edu/repos/iuc/deseq2/deseq2/2.11.40.8+galaxy4\",safe=\"\"))')
curl -sS --fail-with-body -H \"x-api-key: "'$api_key_value" "https://usegalaxy.org/api/tools/$tool_path?io_details=true" | python -c '"'import json,sys; d=json.load(sys.stdin)
def walk(xs,pre=\"\"):
  for x in xs:
    n=x.get(\"name\"); t=x.get(\"type\");
    if t in (\"conditional\",\"repeat\",\"section\"):
      print(pre+n, t, \"cases=\"+str([(c.get(\"value\"),len(c.get(\"inputs\",[]))) for c in x.get(\"cases\",[])]) if t==\"conditional\" else \"\")
      if t==\"conditional\":
        for c in x.get(\"cases\",[]): walk(c.get(\"inputs\",[]),pre+n+\"[\"+str(c.get(\"value\"))+\"]/\")
      else: walk(x.get(\"inputs\",[]),pre+n+\"/\")
    else: print(pre+n,t)
walk(d.get(\"inputs\",[]))' "

